import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import yaml from 'js-yaml';
import { buildPatches, REPO_ROOT } from './build-agent-preset-patches.mjs';

// Installation supplies real package identity and entry metadata. Runtime resources
// belong to the single controller; generated presets remain its definition inputs.
export function buildDshBundle({ check = false, root = REPO_ROOT, descriptor } = {}) {
  const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
  const identity = descriptor || pkg.qqBridge?.instance;
  if (!pkg.name || !identity?.entryId || identity.entryId !== identity.settingsNamespace
    || (identity.bundleName !== undefined && identity.bundleName !== pkg.name)) throw Error('Bundle requires matching package and instance entry identity');
  const results = buildPatches({ check, root });
  const patches = [{ insert: [{ id: identity.entryId, name: pkg.name, config: {} }] }];
  const outputs = {
    'cordis.patch.yml': '# Generated by scripts/build-dsh-bundle.mjs. Edit instance metadata and preset sources instead.\n' + yaml.dump(patches, { lineWidth: -1, noRefs: true }),
    'dsh-client.js': '// Generated by scripts/build-dsh-bundle.mjs from the launcher client.\n' + fs.readFileSync(path.join(root, 'plugins/qq-launcher/lib/client.js'), 'utf8').replace("id: 'qq-launcher'", 'id: ' + JSON.stringify(pkg.name)),
  };
  for (const [relative, content] of Object.entries(outputs)) {
    const file = path.join(root, relative), changed = !fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== content;
    if (changed && !check) fs.writeFileSync(file, content);
    results.push({ file, changed });
  }
  return results;
}
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check'), out = buildDshBundle({ check });
  console.log(JSON.stringify({ files: out.length, stale: out.filter(row => row.changed).map(row => path.relative(REPO_ROOT, row.file)), check }));
  if (check && out.some(row => row.changed)) process.exitCode = 1;
}
